-- Aurora schema sync, part 2: the 19 views missing on Aurora (VTID-04755).
-- Generated 2026-10-09 from the Supabase catalog, flattened to one statement
-- per line for aurora-run-sql.sh. Run LAST (after the FK script), so a view
-- failure can never block the data load. Idempotent (CREATE OR REPLACE).
-- Changes from the Supabase definitions:
--   admin_tenant_analytics: 'x'::tenant_role casts became untyped 'x'
--     literals, which resolve to memberships.role's type whether Aurora has
--     the tenant_role enum or a varchar column.
--   signup_funnel: NOT created. It joins auth.users, which Aurora does not
--     have (auth stays on Supabase GoTrue). Needs a decision before the real
--     switch: drop it, or rebuild it on app_users.
--   Reload PostgREST's schema cache at the end.
CREATE OR REPLACE VIEW public."VtidLedger" WITH (security_invoker=on) AS  SELECT vtid, layer, module, status, title, summary, created_at, updated_at, description, id, is_test, metadata, task_family, task_module, task_type, assigned_to, tenant, parent_vtid, deleted_at, deleted_by, delete_reason, voided_at, voided_reason FROM vtid_ledger;
CREATE OR REPLACE VIEW public.admin_system_health WITH (security_invoker=on) AS  SELECT ( SELECT count(*) AS count FROM memberships) AS total_memberships, ( SELECT count(*) AS count FROM memberships WHERE memberships.status = 'active'::text) AS active_memberships, ( SELECT count(*) AS count FROM tenants) AS total_tenants, ( SELECT count(*) AS count FROM message_threads) AS total_threads, ( SELECT count(*) AS count FROM global_message_threads) AS total_global_threads, ( SELECT count(*) AS count FROM messages) AS total_messages, ( SELECT count(*) AS count FROM global_messages) AS total_global_messages;
CREATE OR REPLACE VIEW public.admin_tenant_analytics WITH (security_invoker=on) AS  SELECT t.tenant_id, t.name AS tenant_name, t.slug AS tenant_slug, count(DISTINCT m.user_id) AS total_users, count(DISTINCT CASE WHEN m.status = 'active'::text THEN m.user_id ELSE NULL::uuid END) AS active_users, count(DISTINCT CASE WHEN m.role = 'admin' THEN m.user_id ELSE NULL::uuid END) AS admin_count, count(DISTINCT CASE WHEN m.role = 'staff' THEN m.user_id ELSE NULL::uuid END) AS staff_count, count(DISTINCT CASE WHEN m.role = 'professional' THEN m.user_id ELSE NULL::uuid END) AS professional_count, count(DISTINCT CASE WHEN m.role = 'patient' THEN m.user_id ELSE NULL::uuid END) AS patient_count FROM tenants t LEFT JOIN memberships m ON m.tenant_id = t.tenant_id GROUP BY t.tenant_id, t.name, t.slug;
CREATE OR REPLACE VIEW public.agent_personas_registry WITH (security_invoker=on) AS  SELECT id, key, display_name, role, voice_id, system_prompt, intake_schema_ref, handles_kinds, handoff_keywords, greeting_templates, status, version, updated_at FROM agent_personas WHERE status = 'active'::text;
CREATE OR REPLACE VIEW public.agent_runs_unified WITH (security_invoker=true) AS  SELECT 'dev_autopilot:'::text || e.id::text AS run_key, 'dev_autopilot'::text AS plane, COALESCE(e.metadata ->> 'executor'::text, 'dev-autopilot-executor'::text) AS agent_id, e.id::text AS source_id, CASE WHEN e.status = ANY (ARRAY['completed'::text, 'self_healed'::text]) THEN 'succeeded'::text WHEN e.status = ANY (ARRAY['failed'::text, 'failed_escalated'::text, 'reverted'::text]) THEN 'failed'::text WHEN e.status = ANY (ARRAY['cancelled'::text, 'rejected'::text, 'archived'::text, 'auto_archived'::text]) THEN 'cancelled'::text WHEN e.status = 'awaiting_approval'::text THEN 'awaiting_approval'::text WHEN e.status = 'cooling'::text THEN 'queued'::text WHEN e.status = ANY (ARRAY['ci'::text, 'merging'::text, 'deploying'::text, 'verifying'::text]) THEN 'waiting_signal'::text ELSE 'running'::text END AS status, e.status AS source_status, COALESCE(r.activated_vtid, e.self_healing_vtid) AS vtid, NULL::uuid AS tenant_id, NULL::uuid AS user_id, CASE WHEN e.parent_execution_id IS NOT NULL THEN 'dev_autopilot:'::text || e.parent_execution_id::text ELSE NULL::text END AS parent_run_key, COALESCE(r.source_type, 'dev_autopilot'::text) AS created_via, "left"(r.title, 200) AS title, e.metadata ->> 'error'::text AS error, e.pr_url AS result_ref, e.created_at, e.updated_at, e.completed_at FROM dev_autopilot_executions e LEFT JOIN autopilot_recommendations r ON r.id = e.finding_id UNION ALL SELECT 'community_autopilot:'::text || a.id::text AS run_key, 'community_autopilot'::text AS plane, a.automation_id AS agent_id, a.id::text AS source_id, CASE WHEN a.status = 'completed'::text THEN 'succeeded'::text WHEN a.status = 'failed'::text THEN 'failed'::text WHEN a.status = ANY (ARRAY['skipped'::text, 'cancelled'::text]) THEN 'cancelled'::text ELSE 'running'::text END AS status, a.status AS source_status, NULL::text AS vtid, a.tenant_id, NULL::uuid AS user_id, NULL::text AS parent_run_key, COALESCE(a.trigger_type, 'scheduler'::text) AS created_via, a.automation_id AS title, a.error_message AS error, NULL::text AS result_ref, a.created_at, COALESCE(a.completed_at, a.started_at, a.created_at) AS updated_at, a.completed_at FROM automation_runs a UNION ALL SELECT 'self_healing:'::text || s.id::text AS run_key, 'self_healing'::text AS plane, 'self-healing'::text AS agent_id, s.id::text AS source_id, CASE WHEN s.outcome = ANY (ARRAY['fixed'::text, 'resolved'::text, 'success'::text]) THEN 'succeeded'::text WHEN s.outcome = ANY (ARRAY['failed'::text, 'rolled_back'::text, 'escalated'::text, 'error'::text]) THEN 'failed'::text WHEN s.resolved_at IS NOT NULL THEN 'succeeded'::text ELSE 'running'::text END AS status, s.outcome AS source_status, s.vtid, NULL::uuid AS tenant_id, NULL::uuid AS user_id, NULL::text AS parent_run_key, 'event'::text AS created_via, "left"((COALESCE(s.failure_class, ''::text) || ' '::text) || COALESCE(s.endpoint, ''::text), 200) AS title, NULL::text AS error, NULL::text AS result_ref, s.created_at, COALESCE(s.resolved_at, s.created_at) AS updated_at, s.resolved_at AS completed_at FROM self_healing_log s UNION ALL SELECT 'native:'::text || n.id::text AS run_key, n.plane, n.agent_id, n.id::text AS source_id, n.status, n.status AS source_status, n.vtid, n.tenant_id, n.user_id, CASE WHEN n.parent_run_id IS NOT NULL THEN 'native:'::text || n.parent_run_id::text ELSE NULL::text END AS parent_run_key, n.created_via, "left"(n.intent, 200) AS title, n.error, n.result_ref ->> 'url'::text AS result_ref, n.created_at, n.updated_at, n.completed_at FROM agent_runs n WHERE (n.metadata -> 'mirror_of'::text) IS NULL;
CREATE OR REPLACE VIEW public.commandhub_board_visible WITH (security_invoker=on) AS  SELECT vtid, status, is_terminal, terminal_outcome, updated_at FROM oasis_tasks t WHERE is_terminal = false AND (status = ANY (ARRAY['allocated'::text, 'scheduled'::text, 'in_progress'::text]));
CREATE OR REPLACE VIEW public.gemini_cost_daily WITH (security_invoker=on) AS  SELECT date_trunc('day'::text, created_at)::date AS day, feature, model, count(*) AS calls, sum(prompt_tokens) AS prompt_tokens, sum(completion_tokens) AS completion_tokens, sum(total_tokens) AS total_tokens, avg(latency_ms)::integer AS avg_latency_ms, count(*) FILTER (WHERE status = 'error'::text) AS errors, count(*) FILTER (WHERE status = 'fallback'::text) AS fallbacks FROM gemini_call_log GROUP BY (date_trunc('day'::text, created_at)::date), feature, model ORDER BY (date_trunc('day'::text, created_at)::date) DESC, (count(*)) DESC;
CREATE OR REPLACE VIEW public.intent_compass_alignment WITH (security_invoker=on) AS  SELECT ui.intent_id, ui.requester_user_id, ui.requester_vitana_id, ui.intent_kind, lc.category AS active_compass_category, lc.primary_goal AS active_compass_goal, COALESCE(icb.boost_weight, 0::numeric) AS compass_boost_weight, icb.boost_weight IS NOT NULL AS is_compass_aligned FROM user_intents ui LEFT JOIN life_compass lc ON lc.user_id = ui.requester_user_id AND lc.is_active = true LEFT JOIN intent_compass_boost icb ON icb.compass_category = lc.category AND icb.intent_kind = ui.intent_kind;
CREATE OR REPLACE VIEW public.intent_open_asks WITH (security_invoker=on) AS  SELECT intent_id, requester_user_id, requester_vitana_id, tenant_id, intent_kind, category, title, scope, kind_payload, match_count, created_at, expires_at FROM user_intents ui WHERE status = 'open'::text AND visibility = 'public'::text AND match_count = 0 AND (expires_at IS NULL OR expires_at > now());
CREATE OR REPLACE VIEW public.live_rooms_public WITH (security_invoker=on) AS  SELECT id, tenant_id, title, topic_keys, host_user_id, starts_at, ends_at, status, created_at, updated_at, access_level, jsonb_build_object('price', metadata -> 'price'::text, 'stream_type', metadata -> 'stream_type'::text, 'enable_replay', metadata -> 'enable_replay'::text, 'cover_image_url', metadata -> 'cover_image_url'::text) AS metadata FROM live_rooms;
CREATE OR REPLACE VIEW public.local_heroes_weekly WITH (security_invoker=on) AS  SELECT COALESCE(p.city, 'Unknown'::text) AS city, ur.vitana_id, ur.user_id, p.display_name, p.avatar_url, ur.completed_count, ur.avg_rating, ur.ratings_count, ur.last_active_at, rank() OVER (PARTITION BY (COALESCE(p.city, 'Unknown'::text)) ORDER BY ur.completed_count DESC, ur.avg_rating DESC NULLS LAST, ur.last_active_at DESC NULLS LAST) AS city_rank FROM user_reputation ur JOIN profiles p USING (user_id) WHERE ur.last_active_at > (now() - '14 days'::interval) OR ur.completed_count > 0;
CREATE OR REPLACE VIEW public.popular_podcast_shows WITH (security_invoker=on) AS  SELECT pm.series_name AS show_name, pm.host_name, count(DISTINCT pm.media_id) AS episode_count, max(mu.created_at) AS latest_episode_date, mu.category, count(DISTINCT pss.user_id) AS subscriber_count FROM podcast_metadata pm JOIN media_uploads mu ON pm.media_id = mu.id LEFT JOIN podcast_show_subscriptions pss ON pm.series_name = pss.show_name AND pm.host_name = pss.host_name WHERE mu.status = 'approved'::text AND mu.media_type = 'podcast'::text AND pm.series_name IS NOT NULL GROUP BY pm.series_name, pm.host_name, mu.category ORDER BY (count(DISTINCT pss.user_id)) DESC, (count(DISTINCT pm.media_id)) DESC LIMIT 10;
CREATE OR REPLACE VIEW public.stripe_subscriptions WITH (security_invoker=on) AS  SELECT stripe_subscription_id AS id, tenant_id, status, last_payment_error, user_id, plan_key, current_period_start, current_period_end, cancel_at_period_end, trial_end, stripe_customer_id, metadata, created_at, updated_at FROM user_subscriptions WHERE stripe_subscription_id IS NOT NULL;
CREATE OR REPLACE VIEW public.user_diary_streak WITH (security_invoker=on) AS  WITH entry_days AS ( SELECT diary_entries.user_id, (diary_entries.created_at AT TIME ZONE 'UTC'::text)::date AS entry_day FROM diary_entries GROUP BY diary_entries.user_id, ((diary_entries.created_at AT TIME ZONE 'UTC'::text)::date) ), ranked AS ( SELECT entry_days.user_id, entry_days.entry_day, entry_days.entry_day - row_number() OVER (PARTITION BY entry_days.user_id ORDER BY entry_days.entry_day)::integer AS streak_group FROM entry_days ), streaks AS ( SELECT ranked.user_id, ranked.streak_group, count(*) AS streak_days, max(ranked.entry_day) AS last_day FROM ranked GROUP BY ranked.user_id, ranked.streak_group ) SELECT user_id, streak_days::integer AS current_streak_days, last_day FROM streaks WHERE last_day >= (CURRENT_DATE - '1 day'::interval)::date ORDER BY user_id;
CREATE OR REPLACE VIEW public.user_follow_counts WITH (security_invoker=on) AS  SELECT p.user_id, COALESCE(followers.count, 0::bigint) AS followers_count, COALESCE(following.count, 0::bigint) AS following_count FROM profiles p LEFT JOIN ( SELECT user_follows.following_id AS user_id, count(*) AS count FROM user_follows GROUP BY user_follows.following_id) followers ON followers.user_id = p.user_id LEFT JOIN ( SELECT user_follows.follower_id AS user_id, count(*) AS count FROM user_follows GROUP BY user_follows.follower_id) following ON following.user_id = p.user_id;
CREATE OR REPLACE VIEW public.user_pillar_recent_activity WITH (security_invoker=on) AS  WITH pillar_tags_lookup(pillar, tags) AS ( VALUES ('nutrition'::text,ARRAY['nutrition'::text, 'meal'::text, 'food-log'::text]), ('hydration'::text,ARRAY['hydration'::text, 'water'::text]), ('exercise'::text,ARRAY['movement'::text, 'workout'::text, 'walk'::text, 'steps'::text, 'exercise'::text]), ('sleep'::text,ARRAY['sleep'::text, 'rest'::text, 'recovery'::text]), ('mental'::text,ARRAY['mindfulness'::text, 'mental'::text, 'stress'::text, 'meditation'::text, 'learning'::text, 'journal'::text, 'social'::text, 'community'::text, 'meetup'::text, 'invite'::text, 'group'::text, 'chat'::text, 'leadership'::text, 'connection'::text, 'match'::text]) ), classified AS ( SELECT ce.user_id, pt.pillar, ce.completion_status, ce.completed_at, ce.source_ref_type, ce.metadata FROM calendar_events ce CROSS JOIN pillar_tags_lookup pt WHERE ce.wellness_tags && pt.tags ) SELECT user_id, pillar, max(completed_at) AS last_completed_at, count(*) FILTER (WHERE completion_status = 'completed'::text AND completed_at >= (now() - '24:00:00'::interval)) AS completions_24h, count(*) FILTER (WHERE completion_status = 'completed'::text AND completed_at >= (now() - '7 days'::interval)) AS completions_7d, count(*) FILTER (WHERE completed_at >= (now() - '24:00:00'::interval) AND (source_ref_type = 'pillar_template'::text OR (metadata ->> 'plan_source'::text) = 'template'::text)) AS plan_events_24h FROM classified c GROUP BY user_id, pillar;
CREATE OR REPLACE VIEW public.voice_session_facts_hourly WITH (security_invoker=true) AS  SELECT date_trunc('hour'::text, started_at) AS bucket, tenant_id, surface, role, provider, lang, count(*)::integer AS sessions, count(*) FILTER (WHERE outcome = 'ok'::text)::integer AS ok, count(*) FILTER (WHERE outcome = 'silent'::text)::integer AS silent, count(*) FILTER (WHERE outcome = 'one_way'::text)::integer AS one_way, count(*) FILTER (WHERE outcome = 'dropped'::text)::integer AS dropped, count(*) FILTER (WHERE outcome = 'error'::text)::integer AS error, avg(duration_ms)::integer AS avg_duration_ms, percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (ttfa_ms::double precision))::integer AS p50_ttfa_ms, percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (ttfa_ms::double precision))::integer AS p95_ttfa_ms FROM voice_session_facts f GROUP BY (date_trunc('hour'::text, started_at)), tenant_id, surface, role, provider, lang;
CREATE OR REPLACE VIEW public.vtid_specs WITH (security_invoker=on) AS  SELECT id, vtid, version, title, spec_markdown, spec_hash, status, created_by, created_at FROM oasis_specs;
CREATE OR REPLACE VIEW public.wearable_rollup_7d WITH (security_invoker=on) AS  SELECT user_id, round(avg(sleep_minutes) FILTER (WHERE sleep_minutes IS NOT NULL), 0) AS sleep_avg_minutes, round(avg(sleep_deep_minutes) FILTER (WHERE sleep_deep_minutes IS NOT NULL), 0) AS sleep_deep_avg_minutes, round(avg( CASE WHEN sleep_minutes > 0 THEN sleep_deep_minutes::numeric / NULLIF(sleep_minutes, 0)::numeric * 100::numeric ELSE NULL::numeric END), 2) AS sleep_deep_pct, round(avg(hrv_avg_ms) FILTER (WHERE hrv_avg_ms IS NOT NULL), 2) AS hrv_avg_ms, round(avg(resting_hr) FILTER (WHERE resting_hr IS NOT NULL), 0) AS resting_hr, round(avg(active_minutes) FILTER (WHERE active_minutes IS NOT NULL), 0) AS activity_minutes, sum(workout_count) AS workout_count, max(metric_date) AS latest_date, count(DISTINCT metric_date) AS days_with_data FROM wearable_daily_metrics WHERE metric_date >= (CURRENT_DATE - '7 days'::interval) GROUP BY user_id;
NOTIFY pgrst, 'reload schema';
